from __future__ import annotations

import os
import struct
import subprocess
import sys
import time
from pathlib import Path
from typing import NoReturn, Protocol
from xml.sax.saxutils import escape

import typer
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["Service", "Systemd", "WindowsTask", "png_to_ico", "serve", "service", "task_xml"]

APP_NAME = "delulu-smash"
APP_SERVICE = "delulu-smash.service"
LAUNCHER = REPO_DIR / ".os" / "scripts" / "keybindings" / "delulu-smash.py"
FAVICON = REPO_DIR / "services" / "ui" / "assets" / "favicon.png"
HOTKEY = "CTRL+ALT+J"
# Windows process creation flags (subprocess only defines them on Windows)
CREATE_NO_WINDOW = 0x08000000
DETACHED_PROCESS = 0x00000008
CREATE_NEW_PROCESS_GROUP = 0x00000200


def is_windows() -> bool:
    return sys.platform == "win32"


def state_dir() -> Path:
    """Where the Windows side keeps its log, pid file, task XML and icon."""
    local = os.environ.get("LOCALAPPDATA")
    return (Path(local) if local else Path.home() / "AppData" / "Local") / APP_NAME


def log_file() -> Path:
    return state_dir() / "ui.log"


def pid_file() -> Path:
    return state_dir() / "ui.pid"


class Service(Protocol):
    """What `ds ui` needs from a platform's way of keeping the server running."""

    logs_hint: str

    def restart(self) -> None:
        """Restart the server (start it when stopped); doesn't wait for it to answer."""

    def logs(self, *, lines: int, follow: bool) -> None:
        """Print the server's last lines, and keep printing new ones with follow."""

    def install(self) -> None:
        """Set up the background server and the shortcuts on this machine."""

    def uninstall(self) -> None:
        """Undo install."""


class Systemd:
    """Omarchy: delulu-smash.service, a systemd user unit that `os sync` installs."""

    logs_hint = f"journalctl --user -u {APP_SERVICE}"

    def restart(self) -> None:
        """Restart the unit (starts it when stopped)."""
        run_cmd(["systemctl", "--user", "restart", APP_SERVICE])

    def logs(self, *, lines: int, follow: bool) -> NoReturn:
        """Hand over to journalctl."""
        args = ["journalctl", "--user", "-u", APP_SERVICE, "-n", str(lines), *(["-f"] if follow else [])]
        os.execvp(args[0], args)  # noqa: S606  # fixed command, replaces this process

    def install(self) -> NoReturn:
        """Refused: `os sync` owns the unit on Omarchy."""
        typer.echo(f"On Omarchy the service comes from `os sync` ({APP_SERVICE}); nothing to install.", err=True)
        raise typer.Exit(1)

    def uninstall(self) -> NoReturn:
        """Refused: `os sync` owns the unit on Omarchy."""
        typer.echo(f"On Omarchy the service comes from `os sync` ({APP_SERVICE}); nothing to remove.", err=True)
        raise typer.Exit(1)


def task_xml(command: str, arguments: str, workdir: str, user: str) -> str:
    """Task Scheduler XML: run as `user` while logged on, at their logon, restart on failure.

    InteractiveToken + LeastPrivilege + a logon trigger for this one user is what a normal user
    may create without admin (any-user triggers and highest privileges need admin).
    """
    command, arguments, workdir, user = (escape(value) for value in (command, arguments, workdir, user))
    return f"""<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Description>delulu-smash: keeps the services/ui Reflex app running (ds ui install)</Description>
  </RegistrationInfo>
  <Triggers>
    <LogonTrigger>
      <Enabled>true</Enabled>
      <UserId>{user}</UserId>
    </LogonTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <UserId>{user}</UserId>
      <LogonType>InteractiveToken</LogonType>
      <RunLevel>LeastPrivilege</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <RestartOnFailure>
      <Interval>PT1M</Interval>
      <Count>3</Count>
    </RestartOnFailure>
    <Enabled>true</Enabled>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>{command}</Command>
      <Arguments>{arguments}</Arguments>
      <WorkingDirectory>{workdir}</WorkingDirectory>
    </Exec>
  </Actions>
</Task>
"""


def png_to_ico(png: bytes) -> bytes:
    """An .ico holding one PNG image (read since Windows Vista); shortcuts need an .ico."""
    width, height = struct.unpack(">II", png[16:24])  # the PNG's IHDR
    header = struct.pack("<HHH", 0, 1, 1)  # reserved, type 1 = icon, one image
    entry = struct.pack("<BBBBHHII", width % 256, height % 256, 0, 0, 1, 32, len(png), 6 + 16)
    return header + entry + png


# Makes a .lnk with Windows' own COM object; values come in as env vars, so nothing is quoted.
SHORTCUT_PS = """
$s = (New-Object -ComObject WScript.Shell).CreateShortcut($env:DS_LNK_PATH)
$s.TargetPath = $env:DS_LNK_TARGET
$s.Arguments = $env:DS_LNK_ARGS
$s.WorkingDirectory = $env:DS_LNK_DIR
$s.IconLocation = $env:DS_LNK_ICON
$s.Description = $env:DS_LNK_DESC
if ($env:DS_LNK_HOTKEY) { $s.Hotkey = $env:DS_LNK_HOTKEY }
$s.Save()
"""


def _powershell(script: str, env: dict[str, str] | None = None) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["powershell", "-NoProfile", "-NonInteractive", "-Command", script],
        capture_output=True,
        text=True,
        check=False,
        env={**os.environ, **(env or {})},
        creationflags=CREATE_NO_WINDOW,
    )


def _special_folder(name: str) -> Path:
    """A Windows folder by its .NET name (Desktop, Programs, Startup); follows OneDrive."""
    result = _powershell(f"[Environment]::GetFolderPath('{name}')")
    if result.returncode != 0 or not result.stdout.strip():
        typer.echo(f"Couldn't find the {name} folder: {result.stderr.strip()}", err=True)
        raise typer.Exit(1)
    return Path(result.stdout.strip())


class WindowsTask:
    """Windows: a Task Scheduler task at logon runs `ds ui run` with no console window."""

    TASK = APP_NAME
    logs_hint = "ds ui logs"

    @property
    def pythonw(self) -> Path:
        """The repo venv's windowless Python: runs `ds` and the launcher with no console."""
        return REPO_DIR / ".venv" / "Scripts" / "pythonw.exe"

    def server_args(self) -> list[str]:
        """Arguments for pythonw: `ds ui run`, its output to the log file."""
        return ["-m", "ds.cli", "ui", "run", "--log", str(log_file())]

    def task_exists(self) -> bool:
        """Whether `ds ui install` created the scheduled task."""
        query = ["schtasks", "/Query", "/TN", self.TASK]
        return subprocess.run(query, capture_output=True, check=False).returncode == 0

    def _server_pid(self) -> int | None:
        """The pid `ds ui run` wrote, if that process is still a Python (pids are reused)."""
        try:
            pid = int(pid_file().read_text(encoding="utf-8").strip())
        except (OSError, ValueError):
            return None
        found = subprocess.run(
            ["tasklist", "/FI", f"PID eq {pid}", "/FO", "CSV", "/NH"], capture_output=True, text=True, check=False
        ).stdout.lower()
        return pid if "python" in found else None

    def stop(self) -> None:
        """End the task and kill the server's process tree."""
        if self.task_exists():
            subprocess.run(["schtasks", "/End", "/TN", self.TASK], capture_output=True, check=False)
        if pid := self._server_pid():
            # /T: the whole tree (uv, reflex, bun), else ports 3000 and 8000 stay taken
            run_cmd(["taskkill", "/PID", str(pid), "/T", "/F"])
        pid_file().unlink(missing_ok=True)

    def start(self) -> None:
        """Run the task, or start the server detached when there is none."""
        if self.task_exists():
            run_cmd(["schtasks", "/Run", "/TN", self.TASK])
            return
        # no task (install fell back to the Startup folder, or never ran): start it detached
        typer.echo(f"Starting {APP_NAME} in the background (no scheduled task)")
        subprocess.Popen(
            [str(self.pythonw), *self.server_args()],
            cwd=REPO_DIR,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP | CREATE_NO_WINDOW,
        )

    def restart(self) -> None:
        """Stop, then start (doesn't wait for it to answer)."""
        self.stop()
        self.start()

    def logs(self, *, lines: int, follow: bool) -> None:
        """Print the log file's last lines; with follow, keep printing new ones."""
        path = log_file()
        if not path.exists():
            typer.echo(f"No log yet ({path}): the server hasn't run in the background.")
            return
        with path.open(encoding="utf-8", errors="replace") as handle:
            for line in handle.readlines()[-lines:]:
                typer.echo(line, nl=False)
            while follow:
                line = handle.readline()
                if line:
                    typer.echo(line, nl=False)
                else:
                    time.sleep(0.5)

    def _shortcut(self, path: Path, *, args: str, desc: str, hotkey: str = "") -> None:
        env = {
            "DS_LNK_PATH": str(path),
            "DS_LNK_TARGET": str(self.pythonw),
            "DS_LNK_ARGS": args,
            "DS_LNK_DIR": str(REPO_DIR),
            "DS_LNK_ICON": str(state_dir() / f"{APP_NAME}.ico"),
            "DS_LNK_DESC": desc,
            "DS_LNK_HOTKEY": hotkey,
        }
        result = _powershell(SHORTCUT_PS, env)
        if result.returncode != 0:
            typer.echo(f"Couldn't create {path}: {result.stderr.strip()}", err=True)
            raise typer.Exit(1)
        typer.echo(f"Created shortcut: {path}   (hotkey {hotkey})" if hotkey else f"Created shortcut: {path}")

    def _shortcuts(self) -> dict[str, Path]:
        return {
            "desktop": _special_folder("Desktop") / f"{APP_NAME}.lnk",
            "start_menu": _special_folder("Programs") / f"{APP_NAME}.lnk",
            "startup": _special_folder("Startup") / f"{APP_NAME} server.lnk",
        }

    def install(self) -> None:
        """Create the task (or the Startup fallback), the icon and the two shortcuts."""
        if not self.pythonw.exists():
            typer.echo(f"{self.pythonw} is missing: run `uv sync` in the repo first.", err=True)
            raise typer.Exit(1)
        folder = state_dir()
        folder.mkdir(parents=True, exist_ok=True)
        (folder / f"{APP_NAME}.ico").write_bytes(png_to_ico(FAVICON.read_bytes()))
        shortcuts = self._shortcuts()

        xml = folder / "task.xml"
        domain, user = os.environ.get("USERDOMAIN", ""), os.environ.get("USERNAME", "")
        xml.write_text(
            task_xml(
                command=str(self.pythonw),
                arguments=" ".join(f'"{arg}"' if " " in arg else arg for arg in self.server_args()),
                workdir=str(REPO_DIR),
                user=f"{domain}\\{user}" if domain else user,
            ),
            encoding="utf-16",  # schtasks wants UTF-16, as the XML declaration says
        )
        create = ["schtasks", "/Create", "/TN", self.TASK, "/XML", str(xml), "/F"]
        created = subprocess.run(create, capture_output=True, text=True, check=False)
        if created.returncode == 0:
            typer.echo(f'Created scheduled task "{self.TASK}" (runs at logon, restarts on failure)')
            shortcuts["startup"].unlink(missing_ok=True)  # from an earlier fallback install
        else:
            # eg a policy that blocks tasks without admin: the Startup folder needs none
            typer.echo(f"Couldn't create the scheduled task: {(created.stderr or created.stdout).strip()}", err=True)
            typer.echo("Falling back to the Startup folder (starts at logon; no restart if it crashes).")
            self._shortcut(shortcuts["startup"], args=" ".join(self.server_args()), desc=f"{APP_NAME} server")

        launcher = f'"{LAUNCHER}"'
        self._shortcut(shortcuts["desktop"], args=launcher, desc=f"Open {APP_NAME}", hotkey=HOTKEY)
        self._shortcut(shortcuts["start_menu"], args=launcher, desc=f"Open {APP_NAME}")

    def uninstall(self) -> None:
        """Stop the server, delete the task and every shortcut install made."""
        self.stop()
        if self.task_exists():
            run_cmd(["schtasks", "/Delete", "/TN", self.TASK, "/F"])
        for path in self._shortcuts().values():
            if path.exists():
                path.unlink()
                typer.echo(f"Removed {path}")


def service() -> Service:
    """The way this machine keeps the server running."""
    return WindowsTask() if is_windows() else Systemd()


def serve(cmd: list[str], cwd: Path, log: Path | None) -> int:
    """Run the server as a child and wait for it; its exit code is returned.

    Used instead of exec on Windows, where exec starts a new process and ends this one: Task
    Scheduler and the pid file must keep the process that lives as long as the server. With
    a log, the output goes there and the child gets no console window (the task has none).
    """
    folder = state_dir()
    if is_windows():
        folder.mkdir(parents=True, exist_ok=True)
        pid_file().write_text(str(os.getpid()), encoding="utf-8")
    out = None
    if log:
        log.parent.mkdir(parents=True, exist_ok=True)
        if log.exists():
            log.replace(log.with_suffix(".previous.log"))  # the run before, kept for a crash at start
        out = log.open("wb")
    # the server's output is a file, not a console: UTF-8, else Windows' code page fails on "✓"
    env = {**os.environ, "PYTHONUTF8": "1", "PYTHONIOENCODING": "utf-8", "PYTHONUNBUFFERED": "1"}
    flags = CREATE_NO_WINDOW if (log and is_windows()) else 0
    try:
        child = subprocess.Popen(
            cmd, cwd=cwd, stdout=out, stderr=subprocess.STDOUT if out else None, env=env, creationflags=flags
        )
        try:
            return child.wait()
        except KeyboardInterrupt:
            child.terminate()
            return child.wait()
    finally:
        if out:
            out.close()
        if is_windows():
            pid_file().unlink(missing_ok=True)
